import * as O from './owners.mjs';
import * as M from './model.mjs';
export function ownerUI({state,esc,fmt,btn,badge,modal,input,area,select,lead}){
 const money=n=>n===null?'待补充':'¥'+n.toLocaleString('zh-CN');
 function page(ls){const s=state(),owners=ls.filter(l=>l.existingOwner),vs=owners.flatMap(l=>O.currentVehicles(s,l.id));return `<div class="owner-hero"><div class="eyebrow">OWNER CARE → NEXT OPPORTUNITY</div><h2>从照顾现有车辆，到开启下一段旅程</h2><p>先解决服务需求，确认客户意向，再协助置换。服务记录、权益和下一步任务随客户一起交接。</p><div class="owner-metrics"><span><b>${owners.length}</b> 位车主</span><span><b>${vs.filter(v=>v.tradeIntent==='有意向').length}</b> 辆已确认置换意向</span><span><b>${vs.filter(v=>O.benefitsFor(s,v.id).some(b=>O.benefitState(s,b).state==='待核实')).length}</b> 辆权益待核实</span></div></div><div class="owner-cards">${owners.map(l=>`<article class="panel owner-card" data-lead="${l.id}" tabindex="0"><div class="actions"><span class="owner-tag">现有车主</span>${badge(l.life)}</div><h2>${esc(l.name)} <small>${l.id}</small></h2><p>${O.vehiclesFor(s,l.id).map(v=>esc(v.model)+' · '+v.relationship).join('<br>')}</p><div class="tiny muted">${l.owner?M.person(l.owner).name:'团队池'} · ${l.allowed?'允许联系':'禁止营销联系'}</div><p class="owner-link">查看车辆、服务与权益 →</p></article>`).join('')}</div><p class="form-note">演示数据 · 尚未连接 Excel、Service Record、救援或保修系统。报价由人工输入，所有权益条款均为模拟。</p>`;}
 function detail(id,vid){const s=state(),l=lead(id),v=O.vehicle(s,vid),bs=O.benefitsFor(s,vid),qs=s.quotes.filter(q=>q.vehicle===vid).reverse(),can=s.user==='mgr'||l.owner===s.user;return `<div class="backdrop" data-action="close"></div><aside class="drawer owner-drawer" role="dialog" aria-modal="true" aria-label="车辆与置换详情"><div class="drawer-head"><span>${esc(l.name)} · 车辆与置换</span>${btn('关闭','close')}</div><div class="drawer-body"><div class="actions">${btn('← 线索详情与激活','owner-overview')}<span class="owner-tag">现有车主</span>${badge(l.life)}</div><label class="section-label" for="owner-vehicle">当前查看车辆</label><select id="owner-vehicle" class="owner-select">${O.vehiclesFor(s,id).map(a=>`<option value="${a.id}" ${a.id===vid?'selected':''}>${esc(a.model)} · ${a.relationship} · ${a.vin}</option>`).join('')}</select><div class="owner-journey"><span>① 核实关系与权益</span><span>② 确认置换意向</span><span>③ 检测与参考方案</span><span>④ 主管复核与说明</span></div><div class="detail-grid"><div><small>车辆关系 / 里程</small><b>${v.relationship} · ${v.mileage===null?'里程待核实':v.mileage.toLocaleString()+' km'}</b></div><div><small>置换意向</small><b>${v.tradeIntent}</b></div><div><small>信息来源</small><b>${esc(v.relationSource)}</b></div><div><small>最近车辆信息更新</small><b>${fmt(v.updated)}</b></div></div><p class="form-note">${l.allowed?'联系许可有效':'禁止营销联系；服务核实不会恢复营销许可'} · ${v.rescueOpen?'有进行中救援，应优先解决服务需求':'暂无进行中救援'}。车辆和权益按 VIN 分开记录。</p>${can?`<div class="actions">${btn('创建权益核实任务','owner-queue')}${btn('核实车辆与权益','owner-verify','primary')}${btn('确认置换意向','owner-intent')}</div>`:''}<h3 class="section-label">客户权益 <small>可用性 ≠ 所有项目均承保</small></h3>${bs.map(b=>{const st=O.benefitState(s,b);return `<section class="benefit-card"><div class="actions"><b>${b.name}</b><span class="badge ${st.state==='已确认可用'?'green':'orange'}">${st.state}</span></div><p>${esc(b.scope)}</p><small>${esc(st.reason)}<br>有效至 ${fmt(b.end)}${b.maxMileage!==null?' / '+b.maxMileage.toLocaleString()+' km（先到为准）':''}${b.limit!==null?' · 使用 '+(b.used??'待核实')+' / '+b.limit+' 次':''}<br>不适用：${esc(b.excluded)}<br>${b.contract} · ${b.source} · ${b.verifiedAt?'核实于 '+fmt(b.verifiedAt):'尚未核实'}</small></section>`;}).join('')||'<p class="form-note">历史车辆不展示当前可用权益。</p>'}<h3 class="section-label">Service Record · 救援 · Warranty 使用</h3><div class="timeline">${s.serviceRecords.filter(r=>r.vehicle===vid).sort((a,b)=>b.at-a.at).map(r=>`<div class="event"><b>${r.kind} · ${esc(r.title)}</b><p>${r.status} · ${r.mileage.toLocaleString()} km</p><small>${fmt(r.at)} · ${r.source}<br>${r.note}</small></div>`).join('')||'<p class="form-note">暂未取得记录，不代表从未维修或使用服务。</p>'}</div><h3 class="section-label">现车检查与参考方案</h3><div class="summary">${v.inspection?`参考估值 ${money(v.inspection.value)} · ${fmt(v.inspection.at)}<br>${esc(v.inspection.note)}`:'尚未记录现车检查。服务记录只供核查，不能直接推断车况或折价。'}</div>${can?`<div class="actions">${btn('安排检查任务','owner-inspection-task')}${btn('记录检查估值','owner-inspect')}${btn('生成参考草案','owner-quote','primary')}</div>`:''}<p class="form-note">先确认置换意向，流失客户需在线索详情中重新激活。参考方案以人民币计价；有效期7天，不是正式报价。</p>${qs.map(q=>`<section class="benefit-card"><div class="actions"><b>${esc(q.target)} · v${q.version}</b>${badge(O.quoteState(s,q))}</div><div class="quote-lines"><span>新车参考价</span><b>${money(q.amounts.price)}</b><span>旧车参考估值</span><b>− ${money(q.amounts.trade)}</b><span>现车检测费用</span><b>+ ${money(q.amounts.fee)}</b><span>已确认检测抵扣</span><b>− ${money(q.amounts.deduction)}</b><span>参考补差（未含其他费用）</span><strong>${money(q.amounts.net)}</strong></div><p class="form-note">${esc(q.amounts.reason)}<br>${esc(q.basis)}<br>${q.id} · 有效至 ${fmt(q.expires)}</p>${s.user==='mgr'&&O.quoteState(s,q)==='参考草案'?btn('主管复核此版本','owner-confirm','',`data-id="${q.id}"`):''}</section>`).join('')||'<p class="form-note">暂无方案。缺少金额的草案会保留“待补充”，不会将缺失值当作0。</p>'}${can&&qs.some(q=>O.quoteState(s,q)==='已复核（演示）')?btn('记录客户方案说明','owner-explain'):''}<h3 class="section-label">本车下一步</h3>${M.tasksFor(s,id).filter(t=>t.vehicle===vid).map(t=>`<div class="mini-task"><div><b>${t.type}</b><small>${M.person(t.owner).name} · ${fmt(t.due)} · ${t.due<s.now?'已逾期':t.status}</small></div></div>`).join('')||'<p class="form-note">暂无车辆任务，可从上方创建。</p>'}<p class="form-note">模拟数据，仅用于演示。服务记录、权益条件及价格均未连接真实业务系统。</p></div></aside>`;}
 function action(a,vid,el){const s=state(),v=O.vehicle(s,vid);switch(a){case 'owner-queue':O.queue(s,vid,'verify');break;case 'owner-inspection-task':O.queue(s,vid,'inspection');break;case 'owner-verify':modal('核实车辆与权益（演示）',input('mileage','当前里程 km',v.mileage??'','number')+input('usage','合同期内救援已用次数',O.benefitsFor(s,vid).find(b=>b.kind==='rescue')?.used??'','number')+select('relation','车主关系',[['pending','请选择核实结果'],['confirmed','已核实为当前持有']])+area('note','车辆关系、合同与使用记录的核实依据')+'<p class="form-note">人工模拟核实；确认后仍按期限、里程及次数分别判断权益。</p>',f=>O.verify(s,vid,f));break;case 'owner-intent':modal('确认置换意向',select('value','客户意向',['有意向','暂不考虑'])+area('note','客户明确表达的需求与依据')+'<p class="form-note">记录意向不会自动激活流失线索，也不会恢复营销联系许可。</p>',f=>O.setIntent(s,vid,f.value,f.note));break;case 'owner-inspect':modal('记录现车检查与估值',input('value','旧车参考估值（元）',v.inspection?.value??'','number')+area('note','检查结果、估值来源及估值限制'),f=>O.inspectVehicle(s,vid,f.note,f.value));break;case 'owner-quote':{const optional=(n,l,value='')=>input(n,l,value,'number').replace(' required','');modal('生成置换参考草案',input('target','拟购车型',lead(v.lead).model)+optional('price','新车参考价（元，可待补充）')+optional('trade','旧车参考估值（元，可待补充）',v.inspection?.value??'')+optional('fee','现车检测费用（元，可待补充）')+select('benefit','选择抵扣权益',[['','不使用权益'],...O.benefitsFor(s,vid).filter(b=>b.kind==='inspection').map(b=>[b.id,b.name+' · '+O.benefitState(s,b).state])])+area('basis','价格来源、费用范围与待核实事项')+'<p class="form-note">补差 = 新车价 + 检测费 − 旧车估值 − 已确认检测抵扣。待核实权益不抵扣；生成后查看明细，再由主管复核。</p>',f=>O.createQuote(s,vid,f),'保存参考草案');break;}case 'owner-confirm':modal('主管复核参考方案',area('note','复核依据与限制')+'<p class="form-note">要求7天内现车检查、完整金额及最新草案。此操作不发布正式报价。</p>',f=>O.confirmQuote(s,el.dataset.id,f.note));break;case 'owner-explain':modal('记录客户方案说明',area('note','已说明的权益、限制与客户反馈')+'<p class="form-note">仅记录模拟沟通，不向客户发送消息。</p>',f=>O.explain(s,vid,f.note));break;}}
 return {page,detail,action};
}
